<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Refresh, Setting } from '@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const rows=ref([]),dialogOpen=ref(false),dialogType=ref('day'),quantity=ref(1),requestId=ref(''),requestKey=ref(''),renewRequests=ref({}),notice=ref(''),error=ref(''),loading=ref(false),saving=ref(false);
const available=computed(()=>rows.value.filter(row=>row.status==='available').length),expired=computed(()=>rows.value.filter(row=>row.status==='expired').length);
function newRequestId(prefix){return `${prefix}-${globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}`}
function open(type){quantity.value=1;requestId.value='';requestKey.value='';error.value='';dialogType.value=type;dialogOpen.value=true}
async function load(){loading.value=true;try{rows.value=await apiRequest('slots')}catch(cause){error.value=cause.message;rows.value=[]}finally{loading.value=false}}
async function submit(){const key=`${dialogType.value}:${quantity.value}`;if(requestKey.value!==key){requestKey.value=key;requestId.value=newRequestId('slot')}saving.value=true;error.value='';try{const result=await apiRequest('slots',{method:'POST',body:{type:dialogType.value,quantity:quantity.value,requestId:requestId.value}});dialogOpen.value=false;requestId.value='';requestKey.value='';await load();window.dispatchEvent(new Event('douyinjuhe-billing'));notice.value=`已兑换 ${result.ids.length} 个坑位，扣除 ${result.cost} ${result.kind==='formal'?'正式':'测试'}积分${result.replay?'（已恢复上次提交结果）':''}。`}catch(cause){error.value=cause.message}finally{saving.value=false}}
async function renew(row){let requestId=renewRequests.value[row.id];if(!requestId){requestId=newRequestId('renew');renewRequests.value={...renewRequests.value,[row.id]:requestId}}loading.value=true;try{await apiRequest(`slots/${row.id}/renew`,{method:'POST',body:{quantity:1,requestId}});const next={...renewRequests.value};delete next[row.id];renewRequests.value=next;await load();window.dispatchEvent(new Event('douyinjuhe-billing'));notice.value='坑位已续费。'}catch(cause){error.value=cause.message}finally{loading.value=false}}
const status=row=>({available:'可用',bound:'已绑定',expired:'已过期'}[row.status]||row.status),time=value=>new Date(value).toLocaleString(),boundLabel=row=>row.bound_id?(row.bound_type==='account'?`账号 ${row.bound_id}`:row.bound_type==='official_reply'?`官方回复 ${row.bound_id}`:`${row.bound_type} ${row.bound_id}`):'未绑定';
onMounted(()=>{window.addEventListener('douyinjuhe-session',load);load()});onUnmounted(()=>window.removeEventListener('douyinjuhe-session',load));
</script>
<template><section class="slot-page" aria-label="坑位管理"><div class="slot-summary"><article class="product-card"><div><span class="slot-icon blue"><el-icon><Setting/></el-icon></span><div><strong>坑位日卡</strong><small>1 测试积分 / 1 天</small></div></div><el-button type="primary" @click="open('day')">兑换日卡</el-button></article><article class="product-card"><div><span class="slot-icon green"><el-icon><Setting/></el-icon></span><div><strong>坑位月卡</strong><small>1 正式积分 / 30 天</small></div></div><el-button type="success" @click="open('month')">批量兑换</el-button></article><article class="slot-counts"><div><small>全部坑位</small><b>{{rows.length}}</b></div><div><small>可用坑位</small><b>{{available}}</b></div><div><small>已过期</small><b>{{expired}}</b></div></article></div><section class="slot-table"><div class="slot-heading"><div><h2>坑位管理</h2><small>共 {{rows.length}} 个坑位</small></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="notice" :title="notice" type="success" show-icon @close="notice=''"/><el-alert v-if="error" :title="error" type="error" show-icon @close="error=''"/><el-table v-loading="loading" :data="rows" empty-text="暂无坑位"><el-table-column label="坑位" min-width="190"><template #default="{row}">{{row.id}}</template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{row.type==='day'?'日卡':'月卡'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{status(row)}}</template></el-table-column><el-table-column label="绑定" min-width="220"><template #default="{row}">{{boundLabel(row)}}</template></el-table-column><el-table-column label="激活时间" width="180"><template #default="{row}">{{time(row.created)}}</template></el-table-column><el-table-column label="过期时间" width="180"><template #default="{row}">{{time(row.expires)}}</template></el-table-column><el-table-column label="续费规则" min-width="150"><template #default="{row}">{{row.type==='day'?'1 测试积分 / 天':'1 正式积分 / 30 天'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="renew(row)">续费</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialogOpen" :title="dialogType==='day'?'兑换坑位日卡':'兑换坑位月卡'" width="min(520px,94vw)"><template v-if="dialogType==='day'"><p class="confirm-text">确认兑换 <strong>坑位日卡</strong> 吗？将消耗 1 测试积分，有效期 1 天。</p></template><template v-else><el-form label-position="top"><el-form-item label="兑换数量"><el-input-number v-model="quantity" :min="1" :max="100"/></el-form-item></el-form><p class="cost">1 正式积分 / 30 天　预计消耗 {{quantity}} 正式积分</p></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确认兑换</el-button></template></el-dialog></section></template>
<style scoped>.slot-page{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;min-width:0}.slot-summary{display:grid;grid-template-columns:1fr 1fr .9fr;gap:18px;min-width:0}.product-card,.slot-counts,.slot-table{background:#fff;border-radius:18px;box-shadow:0 4px 12px #35497905;min-width:0}.product-card{padding:22px;min-height:145px}.product-card>div{display:flex;align-items:center;gap:12px;margin-bottom:26px}.product-card .el-button{width:100%;font-weight:700}.product-card strong{display:block;font-size:17px}.product-card small,.slot-counts small,.slot-heading small{display:block;color:#8b99ae;font-size:12px;margin-top:4px}.slot-icon{width:42px;height:42px;border-radius:12px;display:grid;place-items:center}.slot-icon.blue{background:#e9efff;color:#2d65f2}.slot-icon.green{background:#e3f5eb;color:#18a05d}.slot-counts{display:grid;grid-template-columns:repeat(3,1fr);align-items:center;padding:28px 22px}.slot-counts b{display:block;font-size:32px;margin-top:8px;color:#162440}.slot-table{padding:22px;min-height:600px;overflow:hidden}.slot-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.slot-heading h2{font-size:18px;margin:0}.slot-table .el-alert{margin-bottom:14px}.slot-table :deep(.el-table__empty-block){min-height:440px}.confirm-text{line-height:1.8}.cost{color:#62738b}.el-input-number{width:100%}@media(max-width:1000px){.slot-summary{grid-template-columns:1fr 1fr}.slot-counts{grid-column:1/-1}}@media(max-width:650px){.slot-summary{grid-template-columns:minmax(0,1fr)}.slot-counts{grid-column:auto}.slot-table{padding:14px}.slot-heading{align-items:start;gap:12px;flex-wrap:wrap}}</style>
